def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the full separator rows and columns.
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != 0]
    sep = grid[sep_rows[0]][0]

    def segments(size, separators):
        result = []
        start = 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < size:
            result.append((start, size))
        return result

    row_blocks = segments(h, sep_rows)
    col_blocks = segments(w, sep_cols)

    # The color in the first panel of each panel-row determines that row's color.
    row_colors = []
    marker_colors = set()
    for r0, r1 in row_blocks:
        counts = {}
        c0, c1 = col_blocks[0]
        for r in range(r0, r1):
            for c in range(c0, c1):
                v = grid[r][c]
                if v != 0 and v != sep:
                    counts[v] = counts.get(v, 0) + 1
        color = max(counts, key=counts.get)
        row_colors.append(color)
        marker_colors.add(color)

    # Locate the distinct-colored pattern in the non-left panels.
    pattern_counts = {}
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks[1:]:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v != 0 and v != sep and v not in marker_colors:
                        pattern_counts[v] = pattern_counts.get(v, 0) + 1
    pattern_color = max(pattern_counts, key=pattern_counts.get)

    pattern = None
    for r0, r1 in row_blocks:
        for c0, c1 in col_blocks[1:]:
            cells = [(r - r0, c - c0)
                     for r in range(r0, r1)
                     for c in range(c0, c1)
                     if grid[r][c] == pattern_color]
            if cells:
                pattern = cells
                panel_h, panel_w = r1 - r0, c1 - c0
                break
        if pattern is not None:
            break

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(row_blocks):
        for c0, c1 in col_blocks:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = 0
            for dr, dc in pattern:
                out[r0 + dr][c0 + dc] = row_colors[i]

    return out
